const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define region - southern African countries
  const countries = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017');
  const namibia = countries.filter(ee.Filter.eq('country_na', 'Namibia'));
  const botswana = countries.filter(ee.Filter.eq('country_na', 'Botswana'));
  const lesotho = countries.filter(ee.Filter.eq('country_na', 'Lesotho'));
  const region = namibia.merge(botswana).merge(lesotho);

  // 2. Load CHIRPS precipitation data
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/PENTAD');

  // 3. Target period: Dec 2018 + Jan 2019
  const targetPeriod = chirps
    .filterDate('2018-12-01', '2019-02-01')
    .select('precipitation');

  // Check data availability
  const targetCount = targetPeriod.size().getInfo();
  console.log(`Target period images: ${targetCount}`);

  if (targetCount === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Calculate target period average
  const targetSum = targetPeriod.sum();
  const targetMean = targetSum.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation');

  // 5. Long-term baseline: Dec+Jan for each year 2000-2019
  const baselineData = [];

  for (let year = 2000; year <= 2019; year++) {
    const decJanPeriod = chirps
      .filterDate(`${year}-12-01`, `${year+1}-02-01`)
      .select('precipitation');

    const periodCount = decJanPeriod.size().getInfo();
    if (periodCount > 0) {
      const periodSum = decJanPeriod.sum();
      const periodMean = periodSum.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: region,
        scale: 5000,
        maxPixels: 1e9
      }).get('precipitation');

      baselineData.push(periodMean);
    }
  }

  // Check baseline data availability
  console.log(`Baseline periods with data: ${baselineData.length}/20`);

  if (baselineData.length === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 6. Calculate long-term average
  const baselineArray = ee.Array(baselineData);
  const longTermAvg = baselineArray.reduce(ee.Reducer.mean(), [0]);

  // 7. Get values and validate
  const targetVal = targetMean.getInfo();
  const baselineVal = longTermAvg.getInfo()[0];

  // Check for valid pixels
  const pixelCount = targetSum.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Target period avg: ${targetVal?.toFixed(2)} mm`);
  console.log(`Long-term avg: ${baselineVal?.toFixed(2)} mm`);
  console.log(`Valid pixels: ${pixelCount}`);

  // Validation checks
  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (targetVal === null || targetVal === undefined || 
      baselineVal === null || baselineVal === undefined ||
      isNaN(targetVal) || isNaN(baselineVal)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 8. Final comparison
  if (targetVal < baselineVal) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
